const cases=[
{id:4,name:'Bedaya Health',category:'Healthcare',title:'Turning visibility into stronger organic reach.',metric:'109K',label:'organic clicks',second:'+103%',secondLabel:'click growth',challenge:'A competitive medical niche with a gap between existing search visibility and click-through volume.',strategy:'Refined titles and descriptions, implemented relevant structured data, and addressed mobile Core Web Vitals issues including CLS and LCP.',result:'Clicks increased from 53.6K to 109K, while impressions reached 5.06 million. Average position improved from 8.5 to 8.1.'},
{id:2,name:'Botsmsg',category:'Technical SEO',title:'Removing the barriers to organic discovery.',metric:'31 → 652',label:'organic clicks',second:'6.8',secondLabel:'average position',challenge:'An automation website with limited search visibility and reported indexation barriers.',strategy:'Audited crawl issues, refined the XML sitemap and aligned landing-page content with commercial search intent.',result:'The published comparison shows clicks growing from 31 to 652, 43.8K impressions, and average position improving from 24 to 6.8.'},
{id:3,name:'Dr. Kareem Shilwa',category:'Healthcare',title:'Building visibility around patient search needs.',metric:'160K',label:'search impressions',second:'1.57K',secondLabel:'organic clicks',challenge:'A specialist medical profile competing against established healthcare websites.',strategy:'Built topic clusters and internal links around the specialty, targeting specific symptoms and procedure-related search needs.',result:'Impressions increased from 30.8K to 160K. The published case study reports approximately 238% click growth, reaching 1.57K clicks.'},
{id:1,name:'Right Nutritions',category:'Healthcare',title:'A new search presence in a competitive niche.',metric:'434',label:'organic clicks',second:'23.3K',secondLabel:'search impressions',challenge:'A new nutrition and supplements website entering a competitive, trust-sensitive market.',strategy:'Focused on evidence-supported content and a hub-and-spoke internal-linking structure connecting relevant content and product pages.',result:'The case study reports 434 clicks and 23.3K impressions from a zero baseline, with average position 7.6 and CTR of 1.9%.'},
{id:0,name:'Souq Used Furniture',category:'Local SEO',title:'Reaching local customers with buying intent.',metric:'79 → 271',label:'organic clicks',second:'24.6K',secondLabel:'search impressions',challenge:'Strong competition for local used-furniture searches and high-intent transactional keywords.',strategy:'Aligned category pages with buy/sell intent and improved server response and mobile usability.',result:'Clicks increased from 79 to 271, while impressions exceeded 24.6K. Average position improved from 39.7 to 27.7.'}
];
let sources=[],details={};const projects=document.querySelector('#projects'),dialog=document.querySelector('dialog');
function render(filter='All'){projects.innerHTML=cases.filter(c=>filter==='All'||c.category===filter).map(c=>`<article class="project"><img class="project-image" src="assets/case-${c.id}.jpg" alt="${c.name} Google Search Console performance comparison" loading="lazy" data-case="${c.id}" tabindex="0" role="button" aria-label="Open ${c.name} case study"><div class="project-body"><span class="tag">${c.category} / CASE STUDY</span><h3>${c.name}</h3><p>${c.title}</p><div class="project-result"><div><strong>${c.metric}</strong><small>${c.label}</small></div><div><strong>${c.second}</strong><small>${c.secondLabel}</small></div></div><button class="case-button" data-case="${c.id}">Explore case study <span>↗</span></button></div></article>`).join('')}
function openCase(id){
const c=cases.find(c=>c.id===Number(id)),s=sources[c.id],d=details[c.id];
if(!d){document.querySelector('#case-content').innerHTML=`<h2>${c.name}</h2><p>${c.challenge}</p><h3>The approach</h3><p>${c.strategy}</p><h3>The outcome</h3><p>${c.result}</p><p>Full details could not load. Please try again or <a href="${s?s.url:'https://ahmedyehya.medium.com/'}" target="_blank" rel="noopener">read the source case study</a>.</p>`;dialog.showModal();return;}
document.querySelector('#case-content').innerHTML=`<span class="tag">${c.category} / CASE STUDY</span><h2>${c.name}</h2><div class="case-meta"><span>${d.domain}</span><span>Google Search Console</span></div><p class="case-intro">${d.intro}</p><h3>The starting point</h3><p>${d.challenge}</p><h3>What the work involved</h3><ol class="case-steps">${d.steps.map(x=>`<li><h4>${x[0]}</h4><p>${x[1]}</p></li>`).join('')}</ol><h3>Before & after</h3><p class="comparison-note">Last 3 months versus previous 3 months, as labelled in the source screenshot. Exact calendar dates are not displayed.</p><div class="metric-table"><table><caption class="sr-only">${c.name} Search Console performance comparison</caption><thead><tr><th scope="col">Metric</th><th scope="col">Previous 3 months</th><th scope="col">Last 3 months</th></tr></thead><tbody>${d.metrics.map(m=>`<tr><th scope="row">${m[0]}</th><td>${m[1]}</td><td>${m[2]}</td></tr>`).join('')}</tbody></table></div><figure><a href="assets/case-${c.id}.jpg" target="_blank" rel="noopener" aria-label="Open ${c.name} original screenshot at full size"><img src="assets/case-${c.id}.jpg" alt="Original ${c.name} Google Search Console comparison"></a><figcaption>Original performance screenshot · Select to view full size ↗</figcaption></figure><h3>What the numbers tell us</h3><p>${d.insight}</p><div class="case-context"><h4>Reading the result in context</h4><p>${d.limit}</p></div><h3>The takeaway</h3><p>${d.lesson}</p><div class="case-footer"><a class="text-link" href="${s?s.url:'https://ahmedyehya.medium.com/'}" target="_blank" rel="noopener">Read the original case study ↗</a><button class="button primary case-contact">Discuss a similar challenge ↗</button></div>`;
dialog.showModal();dialog.scrollTop=0;document.querySelector('.case-contact').onclick=()=>{dialog.close();document.querySelector('#contact').scrollIntoView({behavior:'smooth'});document.querySelector('#contact-name').focus({preventScroll:true})};}
projects.addEventListener('click',e=>{const t=e.target.closest('[data-case]');if(t)openCase(t.dataset.case)});projects.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('img[data-case]')){e.preventDefault();openCase(e.target.dataset.case)}});document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))});render(b.dataset.filter)}));document.querySelector('.close').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});render();Promise.all([fetch('cases.json').then(r=>r.json()),fetch('case-details.json').then(r=>r.json())]).then(([s,d])=>{sources=s;details=d}).catch(()=>{});
